CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(64) NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(96) NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE role_permissions (role_id UUID NOT NULL REFERENCES roles(id), permission_id UUID NOT NULL REFERENCES permissions(id), PRIMARY KEY (role_id, permission_id));
CREATE TABLE medicine_categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(128) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE warehouses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, type VARCHAR(32) NOT NULL CHECK (type IN ('CENTRAL_WAREHOUSE','DISTRIBUTION_STORE')), address TEXT NOT NULL, latitude NUMERIC(9,6), longitude NUMERIC(9,6), contact_phone VARCHAR(40), status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(160) NOT NULL, role_id UUID NOT NULL REFERENCES roles(id), assigned_warehouse_id UUID REFERENCES warehouses(id), status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE','SUSPENDED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE refresh_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), token_hash VARCHAR(255) NOT NULL UNIQUE, family_id UUID NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, replaced_by UUID, reuse_detected BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE refresh_tokens ADD CONSTRAINT fk_refresh_replaced_by FOREIGN KEY (replaced_by) REFERENCES refresh_tokens(id);
CREATE INDEX idx_refresh_tokens_family ON refresh_tokens(family_id);
CREATE INDEX idx_refresh_tokens_user ON refresh_tokens(user_id);
CREATE TABLE medicines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sku VARCHAR(32) NOT NULL UNIQUE, generic_name VARCHAR(160) NOT NULL, brand_name VARCHAR(160), category_id UUID NOT NULL REFERENCES medicine_categories(id), dosage_form VARCHAR(80) NOT NULL, strength VARCHAR(80) NOT NULL, unit_of_measure VARCHAR(40) NOT NULL, storage_temp VARCHAR(80), min_stock_threshold INTEGER NOT NULL DEFAULT 0 CHECK (min_stock_threshold >= 0), min_receiving_shelf_life_days INTEGER NOT NULL DEFAULT 90 CHECK (min_receiving_shelf_life_days >= 0), status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISCONTINUED')), description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT chk_medicine_sku CHECK (sku ~ '^MED-[A-Z]{2,12}-[0-9]{5}$'));
CREATE INDEX idx_medicines_category ON medicines(category_id);
CREATE TABLE suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(160) NOT NULL, code VARCHAR(32) NOT NULL UNIQUE, contact_email VARCHAR(254), contact_phone VARCHAR(40), address TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE batches (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), batch_number VARCHAR(100) NOT NULL, medicine_id UUID NOT NULL REFERENCES medicines(id), supplier_id UUID NOT NULL REFERENCES suppliers(id), manufacturing_date DATE NOT NULL, expiry_date DATE NOT NULL, initial_quantity INTEGER NOT NULL CHECK (initial_quantity > 0), status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','QUARANTINED','EXPIRED','DEPLETED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_batch_medicine_number UNIQUE(medicine_id,batch_number), CONSTRAINT chk_batch_expiry_after_manufacturing CHECK(expiry_date > manufacturing_date));
CREATE INDEX idx_batches_medicine_expiry ON batches(medicine_id, expiry_date);
CREATE INDEX idx_batches_supplier ON batches(supplier_id);
CREATE TABLE storage_locations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), warehouse_id UUID NOT NULL REFERENCES warehouses(id), zone VARCHAR(32) NOT NULL, rack VARCHAR(32) NOT NULL, shelf VARCHAR(32) NOT NULL, bin_code VARCHAR(64) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_storage_location_bin UNIQUE(warehouse_id, bin_code));
CREATE INDEX idx_storage_locations_warehouse ON storage_locations(warehouse_id);
